+func initRemoteGitSource(action string, args []string, root string) bool {
+	source := initGitSource(action, args)
+	if initURLSchemeRE.MatchString(source) {
+		return initRemoteURL(source)
+	}
+	if m := initGitSourceSCPRE.FindStringSubmatch(source); m != nil {
+		return !initDynamic(m[1]) && !initLoopbackHost(m[1])
+	}
