+
+// initGitSource reads the repository operand, not a destination, refspec or flag value.
+func initGitSource(action string, args []string) string {
+	longValues := " --depth --shallow-since --shallow-exclude --upload-pack --server-option --filter --jobs "
+	var shortValues string
+	switch action {
+	case "clone":
+		longValues += "--template --reference --reference-if-able --origin --branch --revision --separate-git-dir --ref-format --config --bundle-uri "
+		shortValues = "jobuc"
+	case "pull":
+		longValues += "--cleanup --strategy --strategy-option --deepen --refmap --negotiation-tip "
+		shortValues = "jsXo"
+	case "fetch":
+		longValues += "--deepen --refmap --negotiation-tip "
+		shortValues = "jo"
+	}
+	for i := 0; i < len(args); i++ {
+		arg := args[i]
+		if arg == "--" {
+			if i+1 < len(args) {
+				return args[i+1]
+			}
+			return ""
+		}
+		if arg == "-" || !strings.HasPrefix(arg, "-") {
+			return arg
+		}
+		if strings.HasPrefix(arg, "--") {
+			if strings.Contains(longValues, " "+arg+" ") {
+				i++
+			}
+			continue
+		}
+		for j, flag := range arg[1:] {
+			if strings.ContainsRune(shortValues, flag) {
+				if j+2 == len(arg) {
+					i++
+				}
+				break
+			}
+		}
+	}
+	return ""
+}
+
+// initConfiguredGitRemote only checks for the name; it does not resolve its URL.
+func initConfiguredGitRemote(root, name string) bool {
+	if root == "" || name == "" || name == "." || name == ".." || strings.HasPrefix(name, "./") || strings.HasPrefix(name, "../") || strings.HasPrefix(name, "/") || initDynamic(name) {
+		return false
+	}
+	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
+	defer cancel()
+	cmd := exec.CommandContext(ctx, "git", "remote")
+	cmd.Dir = root
+	out, err := cmd.Output()
+	return err == nil && slices.Contains(strings.Split(string(out), "\n"), name)
+}

